static size_t unhex(const char *h, uint8_t *out) {
    size_t n = strlen(h) / 2;
    for (size_t i = 0; i < n; i++) {
        unsigned v;
        sscanf(h + 2 * i, "%2x", &v);
        out[i] = (uint8_t)v;
    }
    return n;
}

int main(void) {
    /* 1. Vorbis setup header whose codebook has dimensions and entries making pow(r + 1, dim) overflow to inf: lookup1_values cast it to int
     * (UBSan: inf is outside the range of representable values of type 'int', stb_vorbis.c:1244). Found by fuzz movie_audio, seed 1, iteration 1168. */
    fuzz_movie_audio(vorbis_lookup_input, sizeof vorbis_lookup_input);
    uint8_t nan_input[sizeof vorbis_nan_hex / 2];
    size_t nan_len = unhex(vorbis_nan_hex, nan_input);
    fuzz_movie_audio(nan_input, nan_len);
    uint8_t big_input[sizeof vorbis_bigbook_hex / 2];
    size_t big_len = unhex(vorbis_bigbook_hex, big_input);
    fuzz_movie_audio(big_input, big_len);

    /* 2. A comment header whose vendor string length is 0xfffffff0: stb_vorbis allocated len + 1 bytes and then looped len times (a 4 GiB allocation and a
     * very long loop from a few bytes; found as allocation-size-too-big by fuzz movie_audio, seed 1, iteration 6). The comment header is not used, so
     * the decoder is now given an empty one and the stream decodes as if the comment were empty. */
    Pkt pk[64];
    int np = demux(mono_ogg, sizeof mono_ogg, pk, 64);
    CHECK(np >= 4, "the mono vector has its headers and audio (%d packets)", np);
    uint8_t comment[] = {3, 'v', 'o', 'r', 'b', 'i', 's', 0xf0, 0xff, 0xff, 0xff, 'a', 'b', 'c', 'd'};
    VorbisPcm *v = vorbispcm_create();
    int frames = 0;
    int16_t out[VORBISPCM_MAX_FRAMES * 2];
    CHECK(vorbispcm_packet(v, pk[0].p, pk[0].n, out, VORBISPCM_MAX_FRAMES, &frames) == AUDIO_OK, "identification header");
    CHECK(vorbispcm_packet(v, comment, sizeof comment, out, VORBISPCM_MAX_FRAMES, &frames) == AUDIO_OK, "hostile comment header is accepted and ignored");
    CHECK(vorbispcm_packet(v, pk[2].p, pk[2].n, out, VORBISPCM_MAX_FRAMES, &frames) == AUDIO_OK && vorbispcm_ready(v), "setup header completes the decoder");
    for (int i = 3; i < np; i++) CHECK(vorbispcm_packet(v, pk[i].p, pk[i].n, out, VORBISPCM_MAX_FRAMES, &frames) >= 0, "audio packet %d decodes", i);
    vorbispcm_destroy(v);
    printf("{\"test\":\"regress_movie_audio\",\"checked\":%d,\"failed\":%d}\n", g_checked, g_failed);
    return g_failed != 0;
}
